<script setup>
import { computed, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useCalibrationStore } from '../stores/calibration'; import { useAuthStore } from '../stores/auth'; import { downloadCsv } from '../services/download'
const store=useCalibrationStore(),auth=useAuthStore(), search=ref(''), filter=ref('all'), show=ref(false), error=ref(''), saving=ref(false), form=ref({name:'',inventoryNumber:'',type:'',department:'',nextCalibrationAt:'',intervalMonths:12})
const list=computed(()=>store.equipment.filter(x=>(String(x.ownerId)===String(auth.user?.id))&&(filter.value==='all'||x.status===filter.value)&&`${x.name}${x.inventoryNumber}${x.department}`.toLowerCase().includes(search.value.toLowerCase())))
const labels={active:'Действующая',due:'Скоро поверка',overdue:'Просрочена',unfit:'Непригоден'}
const router=useRouter()
async function save(){if(!form.value.name||!form.value.inventoryNumber)return;saving.value=true;error.value='';try{await store.addEquipment({...form.value,ownerId:auth.user?.id,ownerName:auth.user?.fullName});show.value=false;form.value={name:'',inventoryNumber:'',type:'',department:'',nextCalibrationAt:'',intervalMonths:12}}catch(e){error.value=e.message||'Не удалось сохранить оборудование'}finally{saving.value=false}}
function exportList(){downloadCsv('equipment.csv',[{key:'name',label:'Наименование'},{key:'inventoryNumber',label:'Инвентарный номер'},{key:'type',label:'Тип'},{key:'department',label:'Подразделение'},{key:'nextCalibrationAt',label:'Следующая поверка'},{key:'status',label:'Статус'}],list.value)}
function createRequest(item){router.push({path:'/requests',query:{equipmentId:item.id,equipmentName:item.name,inventoryNumber:item.inventoryNumber,preferredDate:item.nextCalibrationAt}})}
onMounted(store.loadRemote)
</script>
<template><section class="page"><div class="section-heading"><div><h2>Моё оборудование</h2><p>Добавляйте средства измерений и контролируйте сроки поверки.</p></div><button class="btn-primary" @click="show=true">＋ Добавить оборудование</button></div><div class="toolbar"><input v-model="search" class="search" placeholder="⌕  Поиск по названию, номеру или подразделению"><select v-model="filter" class="select"><option value="all">Все статусы</option><option value="active">Действующие</option><option value="due">Скоро поверка</option><option value="overdue">Просроченные</option></select><button class="btn-outline" @click="exportList">⇩ Экспорт</button></div><div class="table-panel"><table class="data-table"><thead><tr><th>ОБОРУДОВАНИЕ</th><th>ИНВЕНТАРНЫЙ №</th><th>СЛЕДУЮЩАЯ ПОВЕРКА</th><th>СТАТУС</th><th>ДЕЙСТВИЕ</th></tr></thead><tbody><tr v-for="x in list" :key="x.id"><td>{{x.name}}<small class="muted" style="display:block;font-weight:400;margin-top:3px">{{x.type}}</small></td><td>{{x.inventoryNumber}}</td><td>{{new Date(x.nextCalibrationAt).toLocaleDateString('ru-RU')}}</td><td><span :class="['status',x.status]">{{labels[x.status]}}</span></td><td><button v-if="x.status==='due'||x.status==='overdue'" class="btn-primary" @click="createRequest(x)">Создать заявку</button><span v-else class="muted">Не требуется</span></td></tr><tr v-if="!list.length"><td colspan="5" class="empty">Ничего не найдено</td></tr></tbody></table></div><div v-if="show" class="modal-backdrop" @click.self="show=false"><form class="modal" @submit.prevent="save"><h2>Новое оборудование</h2><div class="form-grid"><label class="field full">Наименование<input v-model="form.name" required placeholder="Например, Манометр МП3-Уф"></label><label class="field">Инвентарный номер<input v-model="form.inventoryNumber" required placeholder="МИ-00001"></label><label class="field">Тип<input v-model="form.type" placeholder="Манометр"></label><label class="field">Подразделение<input v-model="form.department" placeholder="Цех №1"></label><label class="field">Дата следующей поверки<input v-model="form.nextCalibrationAt" type="date"></label><label class="field">Межповерочный интервал, мес.<input v-model.number="form.intervalMonths" type="number"></label></div><p v-if="error" class="auth-error">{{error}}</p><div class="modal-actions"><button class="btn-outline" type="button" @click="show=false">Отмена</button><button class="btn-primary" :disabled="saving">{{saving?'Сохранение…':'Сохранить'}}</button></div></form></div></section></template>
